import re

def parse_duration(s):
    """Parse duration string like '1h30m', '45s', '2h' into seconds."""
    total = 0
    for match in re.finditer(r'(\d+)([hms])', s):
        num = int(match.group(1))
        unit = match.group(2)
        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        else:
            total += num
    return total
